import axios from 'axios';

const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:3000/api';

const api = axios.create({
  baseURL: API_URL,
});

api.interceptors.request.use((config) => {
  try {
    const raw = localStorage.getItem('user');
    if (raw) {
      const user = JSON.parse(raw);
      // Support both {token} and {data:{token}} shapes, plus token at top level
      const token = user?.token || user?.data?.token;
      if (token) {
        config.headers.Authorization = `Bearer ${token}`;
      }
    }
  } catch (_) {
    // corrupted localStorage — clear it to avoid infinite loop
    localStorage.removeItem('user');
  }
  return config;
}, (error) => {
  return Promise.reject(error);
});

api.interceptors.response.use(
  (response) => response,
  (error) => {
    if (error.response?.status === 401) {
      // token expired/invalid — force logout
      localStorage.removeItem('user');
      // avoid redirect loop if already on login
      if (window.location.pathname !== '/login') {
        window.location.href = '/login';
      }
    }
    return Promise.reject(error);
  }
);

export default api;

﻿import React, { useState, useEffect, useRef } from "react";
import { AnimatePresence  } from "framer-motion";
import { useTranslation } from "react-i18next";
import { Accessibility, X, Contrast, Type, Minus, Plus } from "lucide-react";

const FONT_STEPS = ["normal", "large", "x-large"];
const FONT_LABELS = { normal: "100%", large: "112%", "x-large": "125%" };
const FONT_SIZES = { normal: "100%", large: "112.5%", "x-large": "125%" };
const save = (p) => { try { localStorage.setItem("pp-a11y", JSON.stringify(p)); } catch {} };
const load = () => { try { return JSON.parse(localStorage.getItem("pp-a11y") || "{}"); } catch { return {}; } };

const AccessibilityWidget = () => {
  const { t } = useTranslation();
  const [open, setOpen] = useState(false);
  const [hc, setHC] = useState(false);
  const [fs, setFS] = useState(0);
  const ref = useRef(null);

  useEffect(() => {
    const p = load();
    if (p.highContrast) { setHC(true); document.documentElement.classList.add("high-contrast"); }
    if (p.fontStep) { setFS(p.fontStep); document.documentElement.style.fontSize = FONT_SIZES[FONT_STEPS[p.fontStep]]; }
  }, []);

  useEffect(() => {
    if (!open) return;
    const clickOut = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    const esc = (e) => { if (e.key === "Escape") setOpen(false); };
    document.addEventListener("mousedown", clickOut);
    document.addEventListener("keydown", esc);
    return () => { document.removeEventListener("mousedown", clickOut); document.removeEventListener("keydown", esc); };
  }, [open]);

  const setContrast = (v) => { setHC(v); document.documentElement.classList.toggle("high-contrast", v); save({ highContrast: v, fontStep: fs }); };
  const setFont = (i) => { setFS(i); document.documentElement.style.fontSize = FONT_SIZES[FONT_STEPS[i]]; save({ highContrast: hc, fontStep: i }); };
  const reset = () => { setContrast(false); setFont(0); };
  const hasChanges = hc || fs > 0;

  return (
    <div ref={ref} className="fixed bottom-5 left-5 z-[60] flex flex-col items-start gap-3">
      <AnimatePresence>
        {open && (
          <motion.div initial={{opacity:0,y:20,scale:0.95}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0,y:20,scale:0.95}} transition={{duration:0.2,ease:"easeOut"}}
            role="dialog" aria-label={t('accessibility.title')}
            className="w-64 bg-card text-card-foreground rounded-3xl shadow-[0_16px_50px_rgba(0,0,0,0.2)] border border-stone-200/80 dark:border-stone-800 overflow-hidden">
            <div className="bg-dark text-footer-text p-4 flex items-center justify-between border-b border-white/10">
              <div className="flex items-center gap-2.5">
                <div className="w-7 h-7 rounded-lg bg-primary/20 border border-primary/40 flex items-center justify-center text-primary"><Accessibility size={15} /></div>
                <span className="font-serif font-bold text-[#faf7f4] text-sm">{t('accessibility.title')}</span>
              </div>
              <button onClick={() => setOpen(false)} aria-label={t('common.close')} className="text-footer-text/70 hover:text-white p-1.5 rounded-full hover:bg-white/10 transition-colors"><X size={15} /></button>
            </div>
            <div className="p-4 space-y-4">
              <div className="flex items-center justify-between gap-3 p-3 rounded-2xl bg-surface dark:bg-stone-900 border border-stone-200/60 dark:border-stone-800">
                <div className="flex items-center gap-2.5">
                  <Contrast size={16} className="text-primary dark:text-amber-300 shrink-0" />
                  <div><p className="text-xs font-bold text-dark dark:text-stone-100 leading-none">{t('accessibility.highContrast')}</p><p className="text-[10px] text-muted-foreground mt-0.5">{t('accessibility.boostVisibility')}</p></div>
                </div>
                <button role="switch" aria-checked={hc} onClick={() => setContrast(!hc)}
                  className={"relative w-10 h-5 rounded-full transition-colors duration-200 border " + (hc ? "bg-primary border-primary" : "bg-stone-200 dark:bg-stone-700 border-stone-300 dark:border-stone-600")}>
                  <span className={"absolute top-0.5 left-0.5 w-4 h-4 bg-white rounded-full shadow transition-transform duration-200 " + (hc ? "translate-x-5" : "translate-x-0")} />
                  <span className="sr-only">{hc ? t('common.cancel') : t('common.confirm')} {t('accessibility.highContrast')}</span>
                </button>
              </div>
              <div className="p-3 rounded-2xl bg-surface dark:bg-stone-900 border border-stone-200/60 dark:border-stone-800 space-y-2.5">
                <div className="flex items-center gap-2">
                  <Type size={16} className="text-primary dark:text-amber-300 shrink-0" />
                  <div><p className="text-xs font-bold text-dark dark:text-stone-100 leading-none">{t('accessibility.textSize')}</p><p className="text-[10px] text-muted-foreground mt-0.5">{t('accessibility.currentSize', { size: FONT_LABELS[FONT_STEPS[fs]] })}</p></div>
                </div>
                <div className="flex items-center gap-2">
                  <button onClick={() => fs > 0 && setFont(fs - 1)} disabled={fs === 0} aria-label={t('common.back')}
                    className="w-8 h-8 rounded-lg bg-stone-100 dark:bg-stone-800 border border-stone-200/70 dark:border-stone-700 flex items-center justify-center hover:bg-primary hover:text-white hover:border-primary disabled:opacity-40 disabled:cursor-not-allowed transition-colors"><Minus size={14} /></button>
                  <div className="flex-1 flex items-center justify-center gap-1.5">
                    {FONT_STEPS.map((_, i) => (
                      <button key={i} onClick={() => setFont(i)} aria-label={FONT_LABELS[FONT_STEPS[i]]}
                        className={"rounded-full transition-all duration-200 " + (i === fs ? "w-5 h-2.5 bg-primary" : "w-2.5 h-2.5 bg-stone-300 dark:bg-stone-600 hover:bg-primary/50")} />
                    ))}
                  </div>
                  <button onClick={() => fs < FONT_STEPS.length - 1 && setFont(fs + 1)} disabled={fs === FONT_STEPS.length - 1} aria-label={t('common.next')}
                    className="w-8 h-8 rounded-lg bg-stone-100 dark:bg-stone-800 border border-stone-200/70 dark:border-stone-700 flex items-center justify-center hover:bg-primary hover:text-white hover:border-primary disabled:opacity-40 disabled:cursor-not-allowed transition-colors"><Plus size={14} /></button>
                </div>
              </div>
              {hasChanges && <button onClick={reset} className="w-full text-xs text-muted-foreground hover:text-primary dark:hover:text-amber-300 transition-colors py-1 font-bold uppercase tracking-wider">{t('accessibility.resetDefaults')}</button>}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
      <motion.button whileHover={{scale:1.08}} whileTap={{scale:0.94}} onClick={() => setOpen(v => !v)}
        aria-label={t('accessibility.title')} aria-expanded={open} title={t('accessibility.title')}
        className={"relative w-12 h-12 rounded-full text-white shadow-[0_8px_25px_rgba(0,0,0,0.18)] flex items-center justify-center border border-white/20 transition-all duration-200 cursor-pointer " + (open || hasChanges ? "bg-dark dark:bg-stone-800 ring-2 ring-primary/50" : "bg-dark/80 dark:bg-stone-800 hover:bg-dark")}>
        <Accessibility size={20} />
        {hasChanges && <span className="absolute -top-0.5 -right-0.5 w-3 h-3 bg-primary rounded-full ring-2 ring-white dark:ring-stone-900" />}
      </motion.button>
    </div>
  );
};

export default AccessibilityWidget;

﻿import React, { useState, useRef, useEffect } from "react";
import { AnimatePresence  } from "framer-motion";
import { useTranslation } from "react-i18next";
import { MessageCircle, X, Send, Package, ArrowRight, Sparkles, Minus, Loader2 } from "lucide-react";
import { FaWhatsapp } from "react-icons/fa6";
import { Link } from "react-router-dom";
import { Input } from "./ui/input";
import api from "../api/axios";

const WHATSAPP_URL = "https://wa.me/254787251690?text=Hi%20PerfectPick%2C%20I%20have%20a%20question";
const WHATSAPP_FALLBACK = "Sorry, I'm having trouble right now — chat with us directly on WhatsApp (+254 787 251 690): https://wa.me/254787251690";

const ChatWidget = () => {
  const { t } = useTranslation();
  const [state, setState] = useState("closed");
  const [message, setMessage] = useState("");
  const [messages, setMessages] = useState([]); // {role:'user'|'assistant', content:string}
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef(null);

  const isOpen = state === "open";
  const isMinimised = state === "minimised";
  const toggle = () => { if (state === "closed") setState("open"); else if (state === "open") setState("minimised"); else setState("open"); };
  const close = () => setState("closed");
  const minimise = () => setState("minimised");

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, loading]);

  const send = async (e) => {
    e.preventDefault();
    const text = message.trim();
    if (!text || loading) return;
    const userMsg = { role: "user", content: text };
    const nextMessages = [...messages, userMsg];
    setMessages(nextMessages);
    setMessage("");
    setLoading(true);
    try {
      const history = nextMessages.slice(-10).map(m => ({ role: m.role, content: m.content }));
      // send only history without last user msg? we include history+message per spec; we send history prior + message
      const { data } = await api.post("/chat", { message: text, history: nextMessages.slice(0, -1).slice(-10).map(m => ({ role: m.role, content: m.content })) });
      const reply = data?.reply?.trim() || WHATSAPP_FALLBACK;
      setMessages(prev => [...prev, { role: "assistant", content: reply }]);
    } catch (err) {
      const status = err?.response?.status;
      const serverMsg = err?.response?.data?.message;
      if (status === 429) {
        setMessages(prev => [...prev, { role: "assistant", content: serverMsg || "You're sending messages too quickly. Please wait a minute and try again." }]);
      } else {
        setMessages(prev => [...prev, { role: "assistant", content: WHATSAPP_FALLBACK }]);
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed bottom-5 right-5 z-[60] flex flex-col items-end gap-3">
      <AnimatePresence>
        {isOpen && (
          <motion.div initial={{opacity:0,y:30,scale:0.92}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0,y:30,scale:0.92}} transition={{duration:0.25,ease:"easeOut"}}
            className="w-[300px] sm:w-[360px] bg-card text-card-foreground rounded-3xl shadow-[0_16px_50px_rgba(0,0,0,0.22)] overflow-hidden border border-stone-200/80 dark:border-stone-800 flex flex-col max-h-[520px]">
            <div className="bg-dark text-footer-text p-4 flex items-center justify-between border-b border-white/10 shrink-0">
              <div className="flex items-center gap-3">
                <div className="relative">
                  <div className="w-9 h-9 rounded-full bg-primary/20 border border-primary/40 flex items-center justify-center text-primary font-serif font-black text-sm">P</div>
                  <span className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-emerald-400 rounded-full ring-2 ring-dark" />
                </div>
                <div>
                  <h3 className="font-serif font-bold text-base text-[#faf7f4] leading-none">{t('chatWidget.assistantName')}</h3>
                  <p className="text-[11px] text-footer-text/70 mt-1 flex items-center gap-1"><Sparkles size={10} className="text-amber-300" /> {t('chatWidget.assistantTitle')}</p>
                </div>
              </div>
              <div className="flex items-center gap-0.5">
                <button onClick={minimise} className="text-footer-text/70 hover:text-white p-1.5 rounded-full hover:bg-white/10 transition-colors" aria-label={t('chatWidget.minimiseChat')}><Minus size={15} /></button>
                <button onClick={close} className="text-footer-text/70 hover:text-white p-1.5 rounded-full hover:bg-white/10 transition-colors" aria-label={t('common.close')}><X size={15} /></button>
              </div>
            </div>
            <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-3 bg-card">
              <div className="bg-surface dark:bg-stone-900/80 p-3.5 rounded-2xl border border-stone-200/60 dark:border-stone-800 text-xs text-medium dark:text-stone-300 leading-relaxed">
                {t('chatWidget.greeting')}
              </div>
              {messages.map((m, i) => (
                <div key={i} className={`p-3 rounded-2xl text-xs leading-relaxed whitespace-pre-wrap ${m.role === 'user' ? 'bg-primary text-white ml-8 rounded-br-md' : 'bg-surface dark:bg-stone-900/80 border border-stone-200/60 dark:border-stone-800 text-medium dark:text-stone-300 mr-4 rounded-bl-md'}`}>
                  {m.content}
                </div>
              ))}
              {loading && (
                <div className="flex items-center gap-2 text-xs text-muted-foreground dark:text-stone-400">
                  <Loader2 size={14} className="animate-spin" /> Pia is typing...
                </div>
              )}
              {/* Permanent WhatsApp handoff — never removed */}
              <div className="pt-2 space-y-2">
                <a href={WHATSAPP_URL} target="_blank" rel="noopener noreferrer"
                  className="w-full p-2.5 rounded-xl border border-emerald-500/30 bg-emerald-50/60 dark:bg-emerald-950/40 hover:bg-emerald-100/60 dark:hover:bg-emerald-900/50 transition-all flex items-center justify-between group">
                  <div className="flex items-center gap-2.5">
                    <div className="w-7 h-7 rounded-lg bg-emerald-500 text-white flex items-center justify-center"><FaWhatsapp size={14} /></div>
                    <div className="text-left"><p className="text-xs font-bold text-emerald-900 dark:text-emerald-300 leading-none">{t('chatWidget.chatOnWhatsApp')}</p><p className="text-[10px] text-emerald-700/80 dark:text-emerald-400/80 mt-0.5">+254 787 251 690</p></div>
                  </div>
                  <ArrowRight size={14} className="text-emerald-600 dark:text-emerald-400 group-hover:translate-x-0.5 transition-transform" />
                </a>
                <Link to="/orders" onClick={close} className="w-full p-2.5 rounded-xl border border-stone-200/70 dark:border-stone-800 bg-surface/50 dark:bg-stone-900/50 hover:bg-surface dark:hover:bg-stone-800/80 transition-all flex items-center justify-between group">
                  <div className="flex items-center gap-2.5">
                    <div className="w-7 h-7 rounded-lg bg-primary/15 text-primary flex items-center justify-center"><Package size={14} /></div>
                    <span className="text-xs font-bold text-dark dark:text-stone-200">{t('chatWidget.trackMyOrder')}</span>
                  </div>
                  <ArrowRight size={14} className="text-primary group-hover:translate-x-0.5 transition-transform" />
                </Link>
              </div>
            </div>
            <form onSubmit={send} className="relative p-3 border-t border-stone-200/40 dark:border-stone-800/60 bg-card shrink-0">
              <Input value={message} onChange={(e) => setMessage(e.target.value)} placeholder={t('chatWidget.typeMessage')} disabled={loading}
                className="h-10 pr-10 rounded-xl bg-surface dark:bg-stone-900 border-stone-200/70 dark:border-stone-700 text-xs" />
              <button type="submit" disabled={!message.trim() || loading} className="absolute right-5 top-[22px] text-primary hover:text-primary-hover disabled:opacity-40 transition-colors p-1" aria-label="Send"><Send size={15} /></button>
            </form>
            <div className="px-4 py-2.5 bg-surface/60 dark:bg-stone-950/60 text-center border-t border-stone-200/40 dark:border-stone-800/60 shrink-0">
              <p className="text-[9px] uppercase tracking-widest text-muted-foreground dark:text-stone-400 font-bold">{t('chatWidget.footer')}</p>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
      <motion.button whileHover={{scale:1.08}} whileTap={{scale:0.94}} onClick={toggle}
        aria-label={isOpen ? t('chatWidget.minimiseChat') : isMinimised ? t('chatWidget.openChat') : t('chatWidget.chatWithPia')}
        aria-expanded={isOpen}
        className="relative w-12 h-12 rounded-full bg-primary hover:bg-primary-hover text-white shadow-[0_8px_25px_rgba(192,128,80,0.4)] flex items-center justify-center border border-white/20 transition-transform duration-200 cursor-pointer">
        <AnimatePresence mode="wait">
          {isOpen ? (
            <motion.div key="minus" initial={{rotate:-90,opacity:0}} animate={{rotate:0,opacity:1}} exit={{rotate:90,opacity:0}}><Minus size={20} /></motion.div>
          ) : (
            <motion.div key="chat" initial={{scale:0,opacity:0}} animate={{scale:1,opacity:1}} exit={{scale:0,opacity:0}} className="relative">
              <MessageCircle size={22} fill="currentColor" />
              <span className="absolute -top-1 -right-1 w-2.5 h-2.5 bg-emerald-400 rounded-full ring-2 ring-white dark:ring-stone-900" />
              {isMinimised && <span className="absolute -bottom-1 -left-1 w-2.5 h-2.5 bg-amber-400 rounded-full ring-2 ring-white dark:ring-stone-900 animate-pulse" />}
            </motion.div>
          )}
        </AnimatePresence>
      </motion.button>
    </div>
  );
};

export default ChatWidget;

import React, { useState, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { AnimatePresence  } from 'framer-motion';
import { 
  ShoppingBag, 
  Heart, 
  User, 
  Menu, 
  X, 
  LogOut, 
  LayoutDashboard,
  Sparkles,
  Flame,
  ChevronDown,
  Globe
} from 'lucide-react';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../context/AuthContext';
import { useCart } from '../context/CartContext';
import { useWishlist } from '../context/WishlistContext';
import { Button } from './ui/button';
import { cn } from '../lib/utils';
import api from '../api/axios';
import DarkModeToggle from './DarkModeToggle';

const logoModules = import.meta.glob('../assets/logo.{jpg,jpeg,png,webp}', { eager: true });
const logoEntry   = Object.values(logoModules)[0];
const logoSrc     = logoEntry?.default ?? null;

const Navbar = () => {
  const { t, i18n } = useTranslation();
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [accountOpen, setAccountOpen] = useState(false);
  const { user, logout } = useAuth();
  const { cartCount } = useCart();
  const { wishlist } = useWishlist();
  const location = useLocation();
  const [categories, setCategories] = useState([]);
  const accountRef = React.useRef(null);

  const wishlistCount = wishlist.length;

  const changeLang = (lng) => {
    i18n.changeLanguage(lng);
    localStorage.setItem('pp-lang', lng);
  };

useEffect(() => {
    const fetchCategories = async () => {
        try {
            const { data } = await api.get('/products/category-groups');
            if (data.success && Array.isArray(data.data) && data.data.length > 0) {
                const flat = data.data.flatMap(g => g.categories);
                setCategories(flat);
            } else {
                setCategories(['bags', 'shoes', 'jewelry', 'gifts', 'accessories', 'clothes']);
            }
        } catch (error) {
            setCategories(['bags', 'shoes', 'jewelry', 'gifts', 'accessories', 'clothes']);
        }
    };
    fetchCategories();
}, []);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    setIsOpen(false);
  }, [location]);

  useEffect(() => {
    const handleClickOutside = (e) => {
      if (accountRef.current && !accountRef.current.contains(e.target)) {
        setAccountOpen(false);
      }
    };
    const handleEsc = (e) => {
      if (e.key === 'Escape') setAccountOpen(false);
    };
    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('keydown', handleEsc);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('keydown', handleEsc);
    };
  }, []);

  const isAdmin = user?.isAdmin === true || user?.role === 'admin' || user?.role === 'manager';

  return (
    <nav 
      className={cn(
        "sticky top-0 z-50 w-full transition-all duration-300 border-b",
        scrolled 
          ? "bg-bg/95 dark:bg-stone-900/95 backdrop-blur-md shadow-sm border-border/80 dark:border-stone-800" 
          : "bg-bg/80 dark:bg-stone-900/80 backdrop-blur-sm border-transparent"
      )}
    >
      <div className="container mx-auto px-4 sm:px-6 h-16 sm:h-18 flex items-center justify-between">
        {/* Logo */}
        <Link to="/" className="flex items-center gap-2 group shrink-0" aria-label="Perfect Pick — home">
          <motion.div
            whileHover={{ scale: 1.03 }}
            whileTap={{ scale: 0.97 }}
            className="flex items-center gap-2"
          >
            {logoSrc && (
              <img
                src={logoSrc}
                alt="Perfect Pick logo"
                className="h-9 w-9 rounded-full object-cover border border-primary/20 shadow-sm group-hover:ring-2 group-hover:ring-primary/40 transition-all"
              />
            )}
            <span className="text-xl sm:text-2xl font-serif font-black text-dark dark:text-[#faf7f4] tracking-tight group-hover:text-primary transition-colors leading-none">
              Perfect Pick
            </span>
            {!logoSrc && <span className="w-2 h-2 rounded-full bg-primary inline-block" />}
          </motion.div>
        </Link>

        {/* Desktop Navigation */}
        <div className="hidden md:flex items-center gap-6 lg:gap-8">
          <Link 
            to="/" 
            className={cn(
              "text-sm font-bold transition-colors hover:text-primary dark:hover:text-primary",
              location.pathname === '/' ? "text-primary" : "text-medium dark:text-stone-200"
            )}
          >
            {t('nav.home')}
          </Link>
          <Link 
            to="/new-arrivals" 
            className={cn(
              "text-sm font-bold transition-colors hover:text-primary dark:hover:text-primary flex items-center gap-1.5",
              location.pathname === '/new-arrivals' ? "text-primary" : "text-medium dark:text-stone-200"
            )}
          >
            <Sparkles size={14} className="text-primary" /> {t('nav.newArrivals')}
          </Link>
          <Link 
            to="/trending" 
            className={cn(
              "text-sm font-bold transition-colors hover:text-primary dark:hover:text-primary flex items-center gap-1.5",
              location.pathname === '/trending' ? "text-primary" : "text-medium dark:text-stone-200"
            )}
          >
            <Flame size={14} className="text-amber-500" /> {t('nav.trending')}
          </Link>

          {/* Shop Dropdown */}
          <div className="relative group">
            <button className="text-sm font-bold text-medium dark:text-stone-200 hover:text-primary dark:hover:text-primary transition-colors flex items-center gap-1 cursor-pointer py-2">
